CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE organizations (id uuid PRIMARY KEY, name varchar(200) NOT NULL UNIQUE, slug varchar(200) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL);
CREATE TABLE users (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), email varchar(320) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, first_name varchar(120) NOT NULL, last_name varchar(120) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL);
CREATE TABLE customers (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), first_name varchar(120) NOT NULL, last_name varchar(120), email varchar(320), phone varchar(50), company varchar(200), notes text, source varchar(80), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX idx_customers_org_email ON customers(organization_id, lower(email)); CREATE INDEX idx_customers_org_phone ON customers(organization_id, phone);
CREATE TABLE services (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(200) NOT NULL, slug varchar(220) NOT NULL, short_description text, description text, duration_minutes int, booking_enabled boolean NOT NULL DEFAULT true, featured boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, sort_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL, UNIQUE(organization_id,slug));
CREATE TABLE courses (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(200) NOT NULL, slug varchar(220) NOT NULL, description text, active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,slug));
CREATE TABLE course_sessions (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE spaces (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name varchar(200) NOT NULL, slug varchar(220) NOT NULL, description text, location varchar(255), capacity_min int, capacity_max int, size_square_meters numeric(12,2), active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,slug));
CREATE TABLE space_scenes (id uuid PRIMARY KEY, space_id uuid NOT NULL REFERENCES spaces(id), panorama_url text NOT NULL, title varchar(200), initial_yaw double precision NOT NULL DEFAULT 0, initial_pitch double precision NOT NULL DEFAULT 0, sort_order int NOT NULL DEFAULT 0);
CREATE TABLE space_hotspots (id uuid PRIMARY KEY, scene_id uuid NOT NULL REFERENCES space_scenes(id), title varchar(200) NOT NULL, description text, yaw double precision NOT NULL DEFAULT 0, pitch double precision NOT NULL DEFAULT 0, type varchar(50) NOT NULL, target_scene_id uuid REFERENCES space_scenes(id), amenity_id uuid);
CREATE TABLE availability_rules (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), bookable_type varchar(40) NOT NULL, bookable_id uuid NOT NULL, day_of_week varchar(20) NOT NULL, opens_at time NOT NULL, closes_at time NOT NULL, slot_interval_minutes int NOT NULL DEFAULT 30, buffer_before_minutes int NOT NULL DEFAULT 0, buffer_after_minutes int NOT NULL DEFAULT 0, minimum_notice_minutes int NOT NULL DEFAULT 0, maximum_advance_days int NOT NULL DEFAULT 90, active boolean NOT NULL DEFAULT true);
CREATE TABLE availability_exceptions (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), bookable_type varchar(40) NOT NULL, bookable_id uuid NOT NULL, date date NOT NULL, closed boolean NOT NULL DEFAULT true, opens_at time, closes_at time);
CREATE TABLE blocked_periods (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), bookable_type varchar(40) NOT NULL, bookable_id uuid NOT NULL, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, reason varchar(255));
CREATE TABLE bookings (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), customer_id uuid NOT NULL REFERENCES customers(id), bookable_type varchar(40) NOT NULL, bookable_id uuid NOT NULL, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status varchar(30) NOT NULL, reference varchar(30) NOT NULL UNIQUE, notes text, participants int, layout_id uuid, purpose varchar(255), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, CHECK(start_at < end_at));
ALTER TABLE bookings ADD CONSTRAINT bookings_no_active_overlap EXCLUDE USING gist (bookable_type WITH =, bookable_id WITH =, tstzrange(start_at,end_at,'[)') WITH &&) WHERE (status IN ('PENDING','CONFIRMED','COMPLETED','NO_SHOW'));
CREATE INDEX idx_bookings_resource_time ON bookings(bookable_type,bookable_id,start_at,end_at); CREATE INDEX idx_bookings_org_status ON bookings(organization_id,status);
CREATE TABLE requests (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), customer_id uuid NOT NULL REFERENCES customers(id), type varchar(40) NOT NULL, status varchar(40) NOT NULL, message text, created_at timestamptz NOT NULL);
CREATE INDEX idx_requests_org_status ON requests(organization_id,status);
